/bin/bash -lc "python3 - <<'PY'
p='Task.v';s=open(p).read();start=s.index('Local Lemma open_fvars');end=s.index('Local Lemma otval_scope',start)
s=s[:start]+'''Local Lemma open_fvars e k s : fvars (open_ k s e) ⊆ fvars e ∪ fvars s.
Proof.
  revert k; induction e; intro n; simpl;
    try (destruct (decide (n = k)); simpl);
    intros y Hy; rewrite ?elem_of_union in Hy |- *;
    try apply elem_of_empty in Hy; try contradiction;
    try tauto;
    repeat match goal with
    | IH : forall i : nat, _ |- _ =>
        let H0 := fresh in let H1 := fresh in
        pose proof (IH n y) as H0; pose proof (IH (S n) y) as H1;
        clear IH; rewrite ?elem_of_union in H0, H1
    end; tauto.
Qed.

Local Lemma close_fvars e k s : fvars e ⊆ fvars (open_ k s e).
Proof.
  revert k; induction e; intro n; simpl;
    try (destruct (decide (n = k)); simpl);
    intros y Hy; rewrite ?elem_of_union in Hy |- *;
    try apply elem_of_empty in Hy; try contradiction;
    try tauto;
    repeat match goal with
    | IH : forall i : nat, _ |- _ =>
        let H0 := fresh in let H1 := fresh in
        pose proof (IH n y) as H0; pose proof (IH (S n) y) as H1; clear IH
    end; tauto.
Qed.

'''+s[end:]
open(p,'w').write(s)
PY
rocq c -q -time -R theories oadt -R .rocq-deps/stdpp stdpp Task.v >/tmp/178-timing2 2>&1"

